const profileStore = LumiereProfile.createStore(() => window.localStorage);
const initialProfile = profileStore.load();
let savedProfile = initialProfile.data;
let profileIsSaved = initialProfile.saved;
let profileNotice = initialProfile.error;
const escapeHTML = LumiereProfile.escapeHTML;
const firstName = () => savedProfile.name.split(/\s+/)[0];
const initial = () => Array.from(savedProfile.name)[0].toLocaleUpperCase();
const profileValue = (key, fallback='Not shared yet') => escapeHTML(savedProfile[key] || fallback);
function updateProfileIdentity() {
  document.querySelectorAll('[data-profile-name]').forEach(el => { el.textContent = savedProfile.name; });
  document.querySelectorAll('[data-profile-initial]').forEach(el => { el.textContent = initial(); });
}
function profileOptions(key) {
  return LumiereProfile.choices[key].map(value => `<option value="${escapeHTML(value)}"${savedProfile[key]===value?' selected':''}>${escapeHTML(value)}</option>`).join('');
}
const messagingApps = {whatsapp:{name:'WhatsApp',copy:'Continue the conversation in your everyday chats.',icon:'chat'},telegram:{name:'Telegram',copy:'Make space for a gentle check-in, wherever you are.',icon:'send'},wechat:{name:'WeChat',copy:'Keep your skincare companion close to your daily life.',icon:'chat'}};
function connectionOptions() {
  return `<section class="card padded connections-card" id="connected-apps"><div class="card-heading"><span class="eyebrow">CARE, WHERE YOU ARE</span><span class="tiny-tag">COMING SOON</span></div><h3>Your favourite apps.<br>Your familiar companion.</h3><p class="body-copy">A future way to continue conversations and receive gentle check-ins in an app you already use.</p><div class="connection-list">${Object.entries(messagingApps).map(([key,app])=>`<div class="connection-row"><span class="connection-icon ${key}">${icon(app.icon)}</span><div class="connection-copy"><strong>${app.name}</strong><small>${app.copy}</small><span>Not connected · Preview only</span></div><button class="button outline connection-button" data-action="connect-app" data-provider="${key}" aria-label="Preview ${app.name} connection">Connect${icon('arrow')}</button></div>`).join('')}</div><p class="privacy-description">Display-only options. No sign-in, account linking, contact access, or message delivery is enabled.</p></section>`;
}
const paths = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  spark:'<path d="M12 3c1.2 5.8 3.2 7.8 9 9-5.8 1.2-7.8 3.2-9 9-1.2-5.8-3.2-7.8-9-9 5.8-1.2 7.8-3.2 9-9Z"/><path d="m20 2 .5 1.5L22 4l-1.5.5L20 6l-.5-1.5L18 4l1.5-.5Z"/>',
  scan:'<path d="M8 3H4a1 1 0 0 0-1 1v4m13-5h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m8 0h4a1 1 0 0 0 1-1v-4"/><ellipse cx="12" cy="11" rx="4" ry="5"/><path d="M6 19c1-3 3-4 6-4s5 1 6 4"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
  moon:'<path d="M20.5 14a8.7 8.7 0 0 1-10.4-10.5A8.8 8.8 0 1 0 20.5 14Z"/>',
  chart:'<path d="M4 3v17h17M7 15l4-4 4 2 5-7"/>',
  bottle:'<rect x="8" y="2" width="8" height="4" rx="1"/><path d="M9 6v3l-3 3v9a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1v-9l-3-3V6"/><path d="M9 14h6m-6 4h6"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3Z"/><path d="m8.5 11.5 2.5 2.5 4.5-5"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  x:'<path d="m6 6 12 12M6 18 18 6"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  camera:'<path d="M8 5h8l2 3h3v12H3V8h3l2-3Z"/><circle cx="12" cy="13" r="4"/>',
  heart:'<path d="M20.7 4.7a5.5 5.5 0 0 0-7.8 0l-.9.9-.9-.9a5.5 5.5 0 0 0-7.8 7.8L12 21l8.7-8.5a5.5 5.5 0 0 0 0-7.8Z"/>',
  smile:'<circle cx="12" cy="12" r="9"/><path d="M8 14c2 3 6 3 8 0M8 9h.01M16 9h.01"/>',
  neutral:'<circle cx="12" cy="12" r="9"/><path d="M8 15h8M8 9h.01M16 9h.01"/>',
  frown:'<circle cx="12" cy="12" r="9"/><path d="M8 16c2-3 6-3 8 0M8 9h.01M16 9h.01"/>',
  leaf:'<path d="M20 3c-2 2-8 0-12 4-5 5-2 11 2 12 8 1 12-8 10-16ZM4 21 15 10"/>',
  up:'<path d="m5 16 7-8 4 4 5-8M16 4h5v5"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18M7 14h3m4 0h3m-10 3h3"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  edit:'<path d="m14 5 5 5M4 20l5-1L21 7l-5-5L4 14v6Z"/>',
  drop:'<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z"/>',
  texture:'<path d="M3 7c3-6 6 6 9 0s6 6 9 0M3 12c3-6 6 6 9 0s6 6 9 0M3 17c3-6 6 6 9 0s6 6 9 0"/>',
  send:'<path d="m3 3 18 9-18 9 4-9-4-9Zm4 9h14"/>',
  mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.01"/>',
  upload:'<path d="M4 16v5h16v-5M12 16V3m-5 5 5-5 5 5"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
  pin:'<path d="M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0Z"/><circle cx="12" cy="9" r="2"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
  sliders:'<path d="M4 6h7m4 0h5M4 12h2m4 0h10M4 18h9m4 0h3"/><circle cx="13" cy="6" r="2"/><circle cx="8" cy="12" r="2"/><circle cx="15" cy="18" r="2"/>',
  book:'<path d="M12 5v16M12 5C8 1 3 3 3 3v16s5-2 9 2c4-4 9-2 9-2V3s-5-2-9 2Z"/>',
  chat:'<path d="M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-1l-5 2 2-5a9 9 0 1 1 16-5Z"/><path d="M8 11h8"/>'
};
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.spark}</svg>`;
const arrow = () => icon('arrow');
const round = (name, theme='') => `<span class="round-icon ${theme}">${icon(name)}</span>`;
const intro = (eyebrow, title, description, extra='') => `<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="intro-copy page-subtitle">${description}</p></div>${extra}</div>`;
const textLink = (text, page) => `<a class="text-link" href="#${page}">${text}${arrow()}</a>`;
const days = `<div class="chart-dates"><span>Oct 1</span><span>Oct 4</span><span>Oct 7</span><span>Today</span></div>`;
const miniChart = () => `<svg class="comfort-chart" viewBox="0 0 260 65" preserveAspectRatio="none" role="img" aria-label="Illustrative self-reported comfort increasing from October 1 to October 10"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#c5d0b7" stop-opacity=".5"/><stop offset="100%" stop-color="#e9eddf" stop-opacity=".08"/></linearGradient></defs><path d="M0 50C20 49 29 36 45 38S70 49 87 35s27 3 45-10 30 7 46-6 30 1 43-6 29-4 39-6V65H0Z" fill="url(#chart-fill)"/><path d="M0 50C20 49 29 36 45 38S70 49 87 35s27 3 45-10 30 7 46-6 30 1 43-6 29-4 39-6" fill="none" stroke="#899975" stroke-width="2"/><circle cx="258" cy="7" r="3.5" fill="#899975" stroke="white" stroke-width="2"/></svg>`;
let routinePeriod = 'morning';
let shelfFilter = 'suggested';
const routineData = {
  morning: [{name:'Gently cleanse',short:'A fresh, gentle start',copy:'Use a gentle cleanser you already tolerate. Keep the water lukewarm and pat dry with a soft towel.',time:'Step 1 · Keep it gentle',icon:'drop'}, {name:'Moisturize',short:'A little comfort for your skin',copy:'Apply a simple, fragrance-free moisturizer to slightly damp skin. Introduce one new product at a time and follow its label.',time:'Step 2 · Comfort comes first',icon:'bottle'}, {name:'Protect with SPF',short:'Your everyday essential',copy:'Choose a broad-spectrum, water-resistant SPF 30 or higher. Follow the label for application and reapplication, and use shade and protective clothing.',time:'Step 3 · Before heading outside',icon:'sun'}],
  evening: [{name:'Gently cleanse',short:'Wash the day away',copy:'Gently remove the day’s sunscreen and buildup with a cleanser you tolerate. Avoid scrubbing skin that feels sore or irritated.',time:'Step 1 · A gentle reset',icon:'drop'}, {name:'Moisturize',short:'A calm finish to your day',copy:'Use your familiar moisturizer as directed. A longer routine is not always a better routine; keep things simple while your skin feels unsettled.',time:'Step 2 · A moment of care',icon:'bottle'}]
};
function periodTabs(scope) { return `<div class="tabs" role="group" aria-label="${scope} routine time"><button class="${routinePeriod==='morning'?'active':''}" data-period="morning" aria-pressed="${routinePeriod==='morning'}">${icon('sun')}AM</button><button class="${routinePeriod==='evening'?'active':''}" data-period="evening" aria-pressed="${routinePeriod==='evening'}">${icon('moon')}PM</button></div>`; }
function miniRoutine() { return routineData[routinePeriod].map((step,i)=>`<div class="routine-mini-row"><span class="step-bubble ${i===0?'complete':''}">${i===0?icon('check'):'0'+(i+1)}</span><span><strong>${step.name}</strong><small>${step.short}</small></span><span class="step-status">${i===0?'Done':'To do'}</span></div>`).join(''); }
function overview() {
  return `${intro('A LITTLE MOMENT, JUST FOR YOU',`Good morning, ${escapeHTML(firstName())}.`,'Your skin has a story. Let’s take care of it, together.',`<div class="context-pill">${icon('sun')}<div><strong>${profileValue('city','Your space')}</strong><small>Your location · ${profileIsSaved?'Saved on this device':'Sample profile'}</small></div></div>`)}
  <div class="dashboard-top">
    <section class="hero" aria-labelledby="hero-heading"><img class="hero-photo" src="assets/skincare-portrait.png" alt="Editorial portrait of a woman with natural skin in soft sunlight"><div class="hero-copy"><span class="hero-kicker">${icon('spark')}YOUR PERSONAL BEAUTY ADVISOR</span><h2 id="hero-heading">A little guidance.<br>A little care.<br><em>A glow that’s yours.</em></h2><p>Dry patches? A new concern? Or just not sure where to start? We’re here to listen.</p><a href="#advisor" class="button">Let’s talk about your skin${arrow()}</a></div><span class="photo-note">${icon('heart')}Care that grows with you</span></section>
    <section class="card routine-card"><div class="card-topline"><span class="section-kicker">SMALL STEPS, EVERY DAY</span>${periodTabs('Overview')}</div><h3>Your everyday ritual</h3><p class="card-description">Simple is a beautiful place to start.</p><div class="routine-mini">${miniRoutine()}</div>${textLink('See my routine','routine')}</section>
  </div>
  <div class="section-heading"><h2>A little more in tune with you</h2><span>Thoughtful care. At your own pace.</span></div>
  <div class="dashboard-bottom">
    <section class="card check-card"><div class="card-topline">${round('scan')}<span class="tiny-tag">A MOMENT FOR YOU</span></div><h3>How does your skin feel?</h3><p>No perfect words needed. A feeling or a photo is a lovely place to begin.</p><div class="feeling-list"><button class="feeling-button" data-feeling="Comfortable">${icon('smile')}Good</button><button class="feeling-button" data-feeling="About the same">${icon('neutral')}Okay</button><button class="feeling-button" data-feeling="Uncomfortable">${icon('frown')}A little off</button></div>${textLink('Start a skin check-in','checkin')}</section>
    <section class="card journey-card"><div class="card-topline">${round('leaf','sage')}<span class="tiny-tag">YOUR SAMPLE JOURNEY</span></div><h3>Little steps. Real care.</h3><div class="chart-summary"><span>Your reported comfort</span><span class="improving">${icon('up')}Feeling better</span></div>${miniChart()}${days}${textLink('Explore my skin journey','journey')}</section>
    <section class="card product-card"><div class="card-topline">${round('bottle','plum')}<span class="tiny-tag">LESS, BUT THOUGHTFUL</span></div><h3>Meet your<br>everyday essentials.</h3><p>A simpler shelf, chosen around your life and your budget.</p>${textLink('Explore my shelf','shelf')}<div class="product-visual-backdrop"></div><img class="product-visual" src="assets/moisturizer.svg" alt="Illustrative L’Oréal Paris moisturizer concept packaging"><span class="product-disclaimer">Illustrative packaging</span></section>
  </div>
  <section class="companion-strip"><span class="strip-icon">${icon('calendar')}</span><div><h3>A companion, beyond the conversation.</h3><p>Your next gentle check-in: October 13. A little nudge to see how you’re getting on.</p></div><button class="text-link" data-action="reminders">You set the pace${arrow()}</button></section>`;
}
function advisor() {
  return `${intro('A SPACE TO BE HEARD','Let’s start with how you feel.','You don’t need the right skincare words. Your words are enough.')}
  <div class="split-layout"><div><section class="card chat-card"><div class="chat-header"><span class="advisor-avatar">${icon('spark')}</span><div><h3>Your Lumière advisor</h3><p>Thoughtful guidance, one conversation at a time</p></div><span class="tiny-tag">SAMPLE CONVERSATION</span></div><div class="chat-body"><div class="chat-date">TODAY · OCTOBER 10</div><div class="message user">The sides of my nose are red and dry, and they hurt a little. I’m not really sure what to do.</div><div class="message assistant"><span class="advisor-avatar">${icon('spark')}</span><div><span class="message-name">LUMIÈRE</span><p>That sounds uncomfortable, ${escapeHTML(firstName())}. Let’s take this gently. You don’t need to know exactly what’s happening to ask for help.</p><p>Redness and soreness can have different causes, so I wouldn’t want to assume it’s just dryness. How long has it felt this way? Have you tried a new product recently?</p><p>We can use the preferences you’ve shared as a starting point, and work out the next step together.</p><div class="assistant-options"><button data-prompt="It started a few days ago.">A few days now</button><button data-prompt="I recently tried a new product.">I tried something new</button><button data-action="photo">I’d like to share a photo</button></div></div></div></div><form class="chat-composer" data-form="chat"><label class="sr-only" for="chat-message">Tell Lumière how your skin feels</label><textarea id="chat-message" placeholder="Tell me what’s on your mind…" rows="2"></textarea><div class="composer-actions"><div class="composer-left"><button class="icon-button" type="button" data-action="photo" aria-label="Photo check-in preview">${icon('camera')}</button><button class="icon-button" type="button" data-action="voice" aria-label="Voice input preview">${icon('mic')}</button><span>Your words. Your pace.</span></div><button type="submit" class="send-button" aria-label="Send message preview">${icon('send')}</button></div></form></section><p class="chat-disclaimer">A scripted design preview. Messages are not sent or saved.</p></div>
  <div class="stack"><section class="card padded context-card"><div class="card-heading"><span class="eyebrow">THE LITTLE THINGS THAT MATTER</span>${icon('user')}</div><h3>What I know about you</h3><p class="body-copy">A starting point for care that fits your life. You can change any of this.</p><div class="context-detail"><div class="list-detail"><span>Life stage</span><strong>${profileValue('life')} · ${profileValue('age')}</strong></div><div class="list-detail"><span>Home base</span><strong>${profileValue('city')}</strong></div><div class="list-detail"><span>Your routine</span><strong>${profileValue('routine')}</strong></div><div class="list-detail"><span>Your preference</span><strong>${profileValue('budget')}</strong></div></div><div class="pill-row"><span class="pill">${profileValue('experience')}</span><span class="pill">Comfort first</span></div>${textLink('Edit what I remember','profile')}</section><section class="card padded reassurance-card"><span class="eyebrow">A THOUGHTFUL APPROACH</span><h3>You deserve to feel<br>comfortable in your skin.</h3><p>If a product stings or your symptoms persist, we’ll help you recognize when to stop and seek professional advice.</p><button class="text-link" data-action="care">How we approach skin concerns${arrow()}</button></section></div></div>`;
}
function checkin() {
  return `${intro('GET TO KNOW YOUR SKIN','A check-in, not a judgment.','A photo can add context. How your skin feels matters just as much.')}
  <div class="split-layout"><div><section class="card padded"><div class="scan-layout"><div class="scan-frame" aria-label="Face photo framing guide"><span class="scan-corner tl"></span><span class="scan-corner tr"></span><span class="scan-corner bl"></span><span class="scan-corner br"></span><div class="scan-oval">${icon('user')}</div><span class="scan-caption">NATURAL LIGHT · NO FILTERS · JUST YOU</span></div><div class="scan-copy"><span class="eyebrow">YOUR PHOTO CHECK-IN</span><h3>A clearer picture,<br>together.</h3><p>Share a photo to explore visible appearance and keep a personal record over time.</p><div class="scan-buttons"><button class="button plum" data-action="camera">${icon('camera')}Take a photo</button><button class="button outline" data-action="upload">${icon('upload')}Choose a photo</button></div><label class="consent-line"><input type="checkbox" id="photo-consent">I choose to share a photo for this check-in. I can delete it later.</label><p class="empty-note">Preview only · Your camera and files stay closed.</p></div></div><hr class="divider"><span class="small-label">WHAT A PHOTO MAY HELP US EXPLORE</span><div class="measure-grid"><div class="measure">${icon('drop')}<strong>Visible redness</strong><span>Image colour signal</span></div><div class="measure">${icon('sun')}<strong>Brightness</strong><span>Lighting-dependent</span></div><div class="measure">${icon('texture')}<strong>Surface variation</strong><span>Image texture signal</span></div></div><p class="privacy-description">A photo cannot measure hydration or diagnose a skin condition. Lighting, camera settings, and skin tone can affect these signals.</p></section><div class="help-card">${icon('shield')}<div><strong>Your photos belong to you.</strong><p>Consent before upload. Clear retention choices. Delete whenever you choose.</p></div><a class="text-link" href="#profile" aria-label="Review privacy controls">${arrow()}</a></div></div>
  <section class="card padded checkin-form"><span class="eyebrow">IN YOUR OWN WORDS</span><h3>And how does it feel?</h3><p class="body-copy">A few details help your advisor understand what a photo can’t.</p><hr class="divider"><form data-form="checkin"><div class="field"><label for="feeling">Today, my skin feels…</label><select id="feeling"><option>Choose a feeling</option><option>Comfortable</option><option>About the same</option><option>Uncomfortable</option><option>Dry or tight</option><option>Itchy or irritated</option><option>Painful or stinging</option><option>Something else</option></select></div><div class="field"><label for="area">Where do you notice it?</label><select id="area"><option>Around my nose</option><option>My cheeks</option><option>My forehead</option><option>My chin</option><option>My whole face</option><option>Somewhere else</option></select></div><div class="field"><label for="duration">How long has it felt this way?</label><select id="duration"><option>Just today</option><option>A few days</option><option>More than a week</option><option>It comes and goes</option><option>I’m not sure</option></select></div><div class="field"><label for="skin-notes">Anything else on your mind?</label><textarea id="skin-notes" placeholder="A new product, a change in weather, or anything you’ve noticed…"></textarea></div><button class="button plum full-width" type="submit">Share my check-in${arrow()}</button><p class="field-help">Design preview · Nothing is uploaded or saved.</p></form></section></div>`;
}
function routine() {
  return `${intro('BUILD A HABIT THAT FEELS LIKE YOU','A little ritual. A lasting habit.','Start small, keep it gentle, and make room for real life.',`<button class="button outline" data-action="adapt-routine">${icon('sliders')}Adapt my routine</button>`)}
  <div class="split-layout"><div><div class="routine-toolbar">${periodTabs('Full')}<p>Your ${routinePeriod==='morning'?'morning':'evening'} essentials · Sample plan</p></div><div class="stack">${routineData[routinePeriod].map((step,i)=>`<section class="card routine-step"><span class="step-bubble">0${i+1}</span><div class="step-info"><h3>${step.name}${i===1?'<span class="tiny-tag">YOUR CURRENT FOCUS</span>':''}</h3><p>${step.copy}</p><small>${step.time}</small></div><button class="icon-button" data-action="routine-step" aria-label="Learn about ${step.name.toLowerCase()}">${icon(step.icon)}</button></section>`).join('')}</div><div class="soft-banner" style="margin-top:20px">${icon('heart')}<span>Missed a day? That’s okay. Care is a habit, not a perfect streak.</span></div></div><div class="stack"><section class="card quote-card"><span class="eyebrow">LESS CAN BE LOVELY</span><h3>Your best routine<br>is the one that<br><em>fits your life.</em></h3><p>No ten-step expectations. Just thoughtful essentials and a little consistency.</p></section><section class="card padded"><span class="eyebrow">A GENTLE NUDGE</span><h3>On your schedule</h3><div class="reminder-row"><span>Morning ritual<small>8:00 AM · Beijing time</small></span><button class="switch" role="switch" aria-label="Morning ritual reminder preview" aria-checked="true" data-action="toggle"></button></div><div class="reminder-row"><span>Evening ritual<small>9:00 PM · Beijing time</small></span><button class="switch" role="switch" aria-label="Evening ritual reminder preview" aria-checked="false" data-action="toggle"></button></div><p class="privacy-description">Sample preferences. No notifications are scheduled.</p><button class="text-link" data-action="reminders">Set my own pace${arrow()}</button></section></div></div>`;
}
function journey() {
  return `${intro('CARE THAT CONTINUES','Every little step is part of your story.','Your feelings, your routine, your progress. All in one thoughtful place.',`<a class="button plum" href="#checkin">${icon('scan')}Add a check-in</a>`)}
  <div class="journey-stats"><section class="card stat-card">${round('calendar')}<div><span class="small-label">TIME TOGETHER</span><strong class="stat-value">10 days</strong><p>A beginning worth celebrating</p></div></section><section class="card stat-card">${round('sun','sage')}<div><span class="small-label">MOMENTS OF CARE</span><strong class="stat-value">7 of 10</strong><p>Days you made time for yourself</p></div></section><section class="card stat-card">${round('smile','plum')}<div><span class="small-label">YOUR LATEST CHECK-IN</span><strong class="stat-value">More at ease</strong><p>Self-reported · Sample entries</p></div></section></div>
  <div class="split-layout"><div class="stack"><section class="card padded"><div class="card-heading"><h3>How your skin has felt</h3><span class="tiny-tag">ILLUSTRATIVE DATA</span></div><span class="chart-legend">Your reported comfort · October 1–10</span><svg class="large-chart" viewBox="0 0 650 180" preserveAspectRatio="none" role="img" aria-label="Example comfort trend gradually improving, with day-to-day variation"><path d="M0 30h650M0 90h650M0 150h650" stroke="#eee8dd" stroke-dasharray="4 5"/><path d="M0 143C25 153 45 120 72 124S128 152 150 106s39 14 75-22 49 23 80-5 46-6 80-26 48 21 82-4 48 1 75-15 75 5 108-12L650 180H0Z" fill="#edf1e6"/><path d="M0 143C25 153 45 120 72 124S128 152 150 106s39 14 75-22 49 23 80-5 46-6 80-26 48 21 82-4 48 1 75-15 75 5 108-12" fill="none" stroke="#8f9e7e" stroke-width="2.5"/></svg>${days}<p class="empty-note">A personal reflection, not a clinical score. Feeling better does not confirm a diagnosis or prove a product caused the change.</p></section><section class="card padded"><div class="card-heading"><h3>Notes along the way</h3>${icon('book')}</div><div class="log-entry"><span class="log-date"><strong>10</strong>OCT</span><div><h4>“My skin feels a little more comfortable.”</h4><p>Less tightness around my nose today. Keeping my routine simple.</p></div><span class="tag-green">Check-in</span></div><div class="log-entry"><span class="log-date"><strong>07</strong>OCT</span><div><h4>Finding a routine that fits.</h4><p>Started making a little time for moisturizer in the evening.</p></div><span class="tag-green">Routine</span></div><div class="log-entry"><span class="log-date"><strong>01</strong>OCT</span><div><h4>A first conversation. A fresh start.</h4><p>Shared my skin concerns and what everyday life looks like.</p></div><span class="tag-green">Welcome</span></div></section></div>
  <section class="card padded"><span class="eyebrow">WE’LL KEEP IN TOUCH</span><h3>The care continues.</h3><p class="body-copy">Little check-ins at the right moments, with your permission.</p><hr class="divider"><div class="timeline"><div class="timeline-item"><small>YOUR FIRST CONVERSATION</small><h4>Get to know you</h4><p>Your concerns, your habits, and the kind of care you want.</p></div><div class="timeline-item future"><small>2–3 DAYS AFTER A NEW PRODUCT</small><h4>“How are you getting on?”</h4><p>Has it arrived? Have you started? Does your skin feel comfortable?</p></div><div class="timeline-item future"><small>AFTER 1–2 WEEKS</small><h4>A moment to reflect</h4><p>See how your routine fits and whether anything needs adjusting.</p></div><div class="timeline-item future"><small>WHEN YOU’RE READY</small><h4>Explore your next goal</h4><p>Follow your priorities. There’s no need to add more products.</p></div></div><button class="text-link" data-action="reminders" style="margin-top:22px">Manage my check-ins${arrow()}</button></section></div>`;
}
function shelfCards() {
  if (shelfFilter==='saved' || shelfFilter==='using') return `<div class="shelf-empty">${round(shelfFilter==='saved'?'heart':'bottle')}<h3>${shelfFilter==='saved'?'A little space for your favourites.':'Start with what you already have.'}</h3><p>${shelfFilter==='saved'?'Your saved products will live here once the product tools are connected.':'Your current products will help your advisor build a routine that fits.'}</p><button class="button outline" data-action="add-product">${shelfFilter==='saved'?'Explore the product tool':'Add a product'}${arrow()}</button></div>`;
  return `<article class="card shelf-card"><div class="shelf-image"><span class="tiny-tag">CONCEPT PRODUCT</span><button class="icon-button" data-action="save-product" aria-label="Save hydration essential preview">${icon('heart')}</button><img src="assets/moisturizer.svg" alt="Illustrative moisturizer packaging, not a real product listing"></div><div class="shelf-copy"><span class="eyebrow">L’ORÉAL PARIS · ILLUSTRATIVE</span><h3>Everyday hydration</h3><p>A place for a simple moisturizer that fits your preferences.</p><div class="pill-row"><span class="pill">Budget-aware</span><span class="pill">Simple routine</span></div><div class="match-note"><strong>Why it might fit</strong><br>Your goal is comfort and your preference is to keep things simple. Ingredients and tolerance still need checking.</div><button class="text-link" data-action="product">Explore the match${arrow()}</button></div></article>
  <article class="card shelf-card"><div class="shelf-image sand"><span class="tiny-tag">ROUTINE ESSENTIAL</span><span class="shelf-illustration">${icon('bottle')}</span></div><div class="shelf-copy"><span class="eyebrow">FIND YOUR GENTLE START</span><h3>A familiar cleanser</h3><p>Your existing cleanser may already be a good place to start.</p><div class="pill-row"><span class="pill">Gentle care</span><span class="pill">Use what you have</span></div><div class="match-note"><strong>Before adding anything</strong><br>Tell your advisor what you use now and how your skin feels afterward.</div><a href="#advisor" class="text-link">Talk it through${arrow()}</a></div></article>
  <article class="card shelf-card"><div class="shelf-image rose"><span class="tiny-tag">YOUR DAYTIME ESSENTIAL</span><span class="shelf-illustration">${icon('sun')}</span></div><div class="shelf-copy"><span class="eyebrow">A LITTLE DAILY PROTECTION</span><h3>Make room for SPF</h3><p>Find a sunscreen you feel comfortable using each day.</p><div class="pill-row"><span class="pill">SPF 30+</span><span class="pill">Broad-spectrum</span></div><div class="match-note"><strong>Part of everyday care</strong><br>Texture, price, local availability, and your preferences all matter.</div><button class="text-link" data-action="spf">Find my preferences${arrow()}</button></div></article>`;
}
function shelf() {
  return `${intro('CHOSEN WITH YOU IN MIND','A simpler shelf. A more personal routine.','Thoughtful suggestions start with your needs, your budget, and what you already use.')}
  <div class="filter-row" role="group" aria-label="Product shelf views"><button data-filter="suggested" class="${shelfFilter==='suggested'?'active':''}" aria-pressed="${shelfFilter==='suggested'}">For you</button><button data-filter="saved" class="${shelfFilter==='saved'?'active':''}" aria-pressed="${shelfFilter==='saved'}">Saved for later</button><button data-filter="using" class="${shelfFilter==='using'?'active':''}" aria-pressed="${shelfFilter==='using'}">Currently using</button><button data-action="preferences">${icon('sliders')}My preferences</button></div><div class="shelf-grid">${shelfCards()}</div><div class="soft-banner" style="margin-top:24px">${icon('info')}<span>These are illustrative categories and concept packaging, not live product recommendations. A connected catalogue would verify ingredients, suitability, local availability, and price.</span></div>`;
}
function profile() {
  return `${intro('PERSONAL, ON YOUR TERMS','Good care starts with understanding you.','Choose what to share, and save a profile that feels like you.',`<button class="button outline" data-action="show-connections">${icon('chat')}Messaging apps</button>`)}
  <div class="split-layout"><div class="stack"><section class="card padded"><div class="profile-heading"><span class="avatar" data-profile-initial>${escapeHTML(initial())}</span><div><h3>A little about <span id="profile-heading-name">${escapeHTML(firstName())}</span></h3><p id="profile-summary">${profileIsSaved?'Your saved profile · On this browser and device':'Jamie Chan · A sample profile to make your own'}</p></div></div>
  <form data-form="profile"><div class="form-grid">
    <div class="field"><label for="profile-name">What should we call you?</label><input id="profile-name" name="name" value="${profileValue('name')}" required maxlength="80" autocomplete="off"></div>
    <div class="field"><label for="profile-age">Age range</label><select id="profile-age" name="age">${profileOptions('age')}</select></div>
    <div class="field"><label for="profile-city">Your city</label><input id="profile-city" name="city" value="${profileValue('city','')}" maxlength="100" autocomplete="off"><p class="field-help">City-level context is enough.</p></div>
    <div class="field"><label for="profile-life">Your everyday life</label><select id="profile-life" name="life">${profileOptions('life')}</select></div>
    <div class="field"><label for="profile-experience">Skincare experience</label><select id="profile-experience" name="experience">${profileOptions('experience')}</select></div>
    <div class="field"><label for="profile-budget">Budget preference</label><select id="profile-budget" name="budget">${profileOptions('budget')}</select></div>
    <div class="field span-two"><label for="profile-routine">What does your routine look like?</label><textarea id="profile-routine" name="routine" maxlength="600">${profileValue('routine','')}</textarea></div>
    <div class="field span-two"><label for="profile-sensitivities">Known sensitivities or ingredients you avoid</label><textarea id="profile-sensitivities" name="sensitivities" maxlength="600" placeholder="Share only what you’re comfortable sharing">${profileValue('sensitivities','')}</textarea><p class="field-help">Optional. Leaving this blank means “not shared,” not “no sensitivities.”</p></div>
  </div><div class="form-actions"><button class="button plum" type="submit">Save my preferences${icon('check')}</button><p>Saved only in this browser. No cloud sync.</p></div><p id="profile-save-status" class="profile-save-status" role="status" aria-live="polite">${escapeHTML(profileNotice || (profileIsSaved?'Your saved preferences are loaded.':'Ready when you are. Changes are saved only when you choose Save.'))}</p></form></section>${connectionOptions()}</div>
  <div class="stack"><section class="card padded"><div class="card-heading"><span class="eyebrow">PERSONAL, ON THIS DEVICE</span>${icon('shield')}</div><h3>Your profile stays with you.</h3><p class="body-copy">Saving keeps the details above in this browser, including any sensitivities you choose to share. They stay here after a refresh or restart.</p><p class="privacy-description">Use the same browser and website address to return to your profile. Clearing site data removes it; private browsing may keep it only for that session. Nothing is shared with a messaging app.</p><hr class="divider"><button class="text-link" data-action="memory">Review my saved details${arrow()}</button><br><button class="danger-link" data-action="delete">${icon('trash')}Reset my saved profile</button></section>
  <section class="card padded"><span class="eyebrow">FUTURE PRIVACY CONTROLS</span><h3>Care on your terms</h3><div class="reminder-row"><span>Keep my photo history<small>Preview · Ask before saving each photo</small></span><button class="switch" role="switch" aria-label="Keep photo history preview" aria-checked="false" data-action="toggle"></button></div><div class="reminder-row"><span>Gentle check-ins<small>Preview · A reminder when it’s useful</small></span><button class="switch" role="switch" aria-label="Gentle check-ins preview" aria-checked="true" data-action="toggle"></button></div><p class="privacy-description">These two switches are display-only. Photo storage and reminders are not connected.</p></section>
  <section class="card padded reassurance-card"><span class="eyebrow">JUST SAY THE WORD</span><h3>“I’ve moved to Shanghai.”</h3><p>For now, update and save your city in the form. Conversational updates will be part of a future connected experience.</p>${textLink('Talk to my advisor','advisor')}</section></div></div>`;
}
function saveProfile(form) {
  const result = profileStore.save(Object.fromEntries(new FormData(form)));
  const status = document.getElementById('profile-save-status');
  status.classList.toggle('error', !result.ok);
  if (!result.ok) { status.textContent = result.error; toast(result.error); return; }
  savedProfile = result.data;
  profileIsSaved = true;
  profileNotice = '';
  updateProfileIdentity();
  document.getElementById('profile-heading-name').textContent = firstName();
  document.getElementById('profile-summary').textContent = 'Your saved profile · On this browser and device';
  status.textContent = 'Saved. Your preferences will be here when you return.';
  for (const [key,value] of Object.entries(savedProfile)) form.elements.namedItem(key).value = value;
  toast('Your profile is saved in this browser.');
}
const pageNames={overview:'My overview',advisor:'Beauty advisor',checkin:'Skin check-in',routine:'My routine',journey:'My skin journey',shelf:'My product shelf',profile:'My profile'};
const pages={overview,advisor,checkin,routine,journey,shelf,profile};
let activePage='overview';
function fillIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
function renderPage(resetScroll=true){const requested=location.hash.slice(1);activePage=pages[requested]?requested:'overview';document.getElementById('main').innerHTML=`<div class="view">${pages[activePage]()}</div>`;document.getElementById('page-label').textContent=pageNames[activePage];document.title=`${pageNames[activePage]} · Lumière`;updateProfileIdentity();document.querySelectorAll('[data-page]').forEach(link=>{const current=link.dataset.page===activePage;link.classList.toggle('active',current);if(current)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});closeMenu();if(resetScroll)window.scrollTo({top:0,behavior:'instant'});}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4300);}
const dialog = document.getElementById('detail-dialog');
function feature(name,title,copy){return `<div class="dialog-feature">${icon(name)}<span><strong>${title}</strong>${copy}</span></div>`;}
function showDialog(title,body,iconName='spark'){document.getElementById('dialog-content').innerHTML=`<div class="dialog-icon">${round(iconName)}</div><span class="eyebrow">LUMIÈRE · DESIGN PREVIEW</span><h2 id="dialog-title">${title}</h2>${body}<p class="dialog-footer">This is a front-end concept. No information is sent, no analysis runs, and no reminder or purchase is created.</p>`;dialog.showModal();}
const mobileQuery=window.matchMedia('(max-width:740px)');
function closeMenu(){const sidebar=document.querySelector('.sidebar');sidebar.classList.remove('open');sidebar.inert=mobileQuery.matches;document.querySelector('.workspace').inert=false;document.body.style.overflow='';document.querySelector('.nav-backdrop').hidden=true;document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');}
const actions={
  menu:()=>{const sidebar=document.querySelector('.sidebar');sidebar.inert=false;sidebar.classList.add('open');document.querySelector('.workspace').inert=true;document.body.style.overflow='hidden';document.querySelector('.nav-backdrop').hidden=false;document.querySelector('.menu-toggle').setAttribute('aria-expanded','true');sidebar.querySelector('.sidebar-close').focus();},
  'close-menu':()=>{closeMenu();document.querySelector('.menu-toggle').focus();},
  'close-dialog':()=>dialog.close(),
  'show-connections':()=>{const section=document.getElementById('connected-apps');section.setAttribute('tabindex','-1');section.scrollIntoView({block:'start'});section.focus({preventScroll:true});},
  notifications:()=>showDialog('A little care, at the right time.',`<p>Your future reminder centre brings useful check-ins together.</p><div class="dialog-feature-list">${feature('calendar','October 13 · A gentle follow-up','“Have you had a chance to try your new moisturizer? How does your skin feel?”')}${feature('heart','October 24 · A moment to reflect','“How is your routine fitting into your week?”')}</div><button class="button plum" data-action="reminders">Review check-in preferences${arrow()}</button>`,'bell'),
  reminders:()=>{if(dialog.open)dialog.close();showDialog('You set the pace.',`<p>A companion should fit your life. These are sample settings for the future follow-up service.</p><div class="dialog-feature-list">${feature('calendar','New-product check-in','2–3 days after you confirm a purchase or start date.')}${feature('heart','Routine reflection','Every 2 weeks, with the option to change or pause.')}${feature('moon','Your quiet hours','9:00 PM–8:00 AM · Asia/Shanghai.')}${feature('chat','Your chosen channel','In-app for now. WhatsApp, Telegram, and WeChat appear as upcoming options in My profile.')}</div><div class="field"><label for="reminder-frequency">How often would you like a check-in?</label><select id="reminder-frequency"><option>Every 2 weeks</option><option>Once a week</option><option>Once a month</option><option>Pause check-ins</option></select></div><button class="button plum" data-action="preview-save">Save my pace${icon('check')}</button><br><a class="text-link" href="#profile" data-close-on-nav>Explore messaging apps${arrow()}</a>`,'calendar');},
  'preview-save':()=>toast('Preference preview only — nothing has been scheduled or saved.'),
  photo:()=>showDialog('A photo adds a little context.',`<p>A guided check-in will let you share a photo and describe how your skin feels.</p><div class="dialog-feature-list">${feature('sun','Start with a clear photo','Natural, even light and no beauty filters.')}${feature('shield','Share on your terms','Consent before upload and control over keeping or deleting photos.')}${feature('scan','Explore visible signals','Image colour, brightness, and surface variation — not a diagnosis.')}</div><a class="button plum" href="#checkin" data-close-on-nav>Explore the check-in${arrow()}</a>`,'camera'),
  camera:()=>showDialog('Your photo, your choice.',`<p>The connected version will ask for camera permission after you agree to a photo check-in. No camera is accessed in this prototype.</p><div class="modal-schedule">Face the camera in even daylight, keep your expression relaxed, and avoid filters. If the image is too dark or blurry, the tool should ask for another photo.</div>`,'camera'),
  upload:()=>showDialog('Choose a photo when you’re ready.',`<p>The future upload tool will accept an image after consent, check its quality, and explain what can and cannot be inferred. This preview does not open or upload files.</p>`,'upload'),
  voice:()=>showDialog('Tell it in your own words.',`<p>Voice input is an optional accessibility feature for the next phase. It would turn your spoken description into text for you to review before sending. No microphone is accessed here.</p>`,'mic'),
  care:()=>showDialog('Comfort comes first.',`<p>Redness, flaking, and pain can have several causes. Your advisor should ask about duration, recent products, and severity before suggesting care.</p><div class="dialog-feature-list">${feature('heart','Take irritation seriously','Stop using a product that causes burning or stinging. Persistent or worsening symptoms deserve professional advice.')}${feature('shield','Know when to get help','Severe or rapidly worsening symptoms, swelling, or eye involvement need prompt medical attention. Breathing difficulty is an emergency.')}${feature('bottle','Keep suggestions thoughtful','Do not infer a diagnosis from a photo or prescribe a product from a redness score.')}</div>`,'heart'),
  'adapt-routine':()=>showDialog('Make your routine yours.',`<p>Your advisor would review your existing products, comfort, time, and budget before changing the plan.</p><div class="dialog-feature-list">${feature('clock','Fit your schedule','A few manageable steps for morning and evening.')}${feature('bottle','Start with what you have','Avoid unnecessary purchases and introduce one change at a time.')}${feature('heart','Respond to how you feel','Check tolerance before adding another product.')}</div><a class="button plum" href="#advisor" data-close-on-nav>Talk to my advisor${arrow()}</a>`,'sliders'),
  'routine-step':()=>showDialog('A little guidance for each step.',`<p>In the connected experience, this opens product-specific instructions, order of use, and a way to report irritation. Instructions should come from the verified product label.</p>`,'book'),
  toggle:(button)=>{button.setAttribute('aria-checked',button.getAttribute('aria-checked')==='true'?'false':'true');toast('Setting preview — this change is not saved.');},
  product:()=>showDialog('A match you can understand.',`<p>The product tool should explain every suggestion, not just show a product.</p><div class="dialog-feature-list">${feature('user','Your preferences','Beginner routine, budget-aware, and a focus on comfort.')}${feature('shield','Before a recommendation','Check ingredients, sensitivities, age-appropriate use, and current irritation.')}${feature('pin','Available where you are','Verify the exact local product, currency, and retailer information.')}${feature('book','Clear evidence','Use verified product information and explain uncertainty.')}</div><p>This jar is concept packaging, not an existing product or a confirmed match.</p>`,'bottle'),
  'save-product':()=>toast('Save-for-later preview — no product has been added.'),
  'add-product':()=>showDialog('Start with your own shelf.',`<p>In the connected experience, add a product by name, label photo, or barcode. Your advisor would confirm the exact product and ask how long you’ve used it and how it feels.</p>`,'bottle'),
  preferences:()=>{location.hash='profile';},
  spf:()=>showDialog('Find a comfortable everyday SPF.',`<p>Your advisor would ask about texture, finish, budget, and your current products, then check a verified local catalogue. A sunscreen should offer broad-spectrum SPF 30 or higher; follow its label for use.</p><a class="button plum" href="#profile" data-close-on-nav>Explore my preferences${arrow()}</a>`,'sun'),
  'connect-app':(button)=>{const app=messagingApps[button.dataset.provider];if(!app)return;showDialog(`Lumière, on ${app.name}.`,`<p>In a future version, you could connect ${app.name} to continue conversations and receive check-ins you’ve opted into.</p><div class="dialog-feature-list">${feature('chat','A familiar place to talk','Pick up your skincare conversation in an app you already use.')}${feature('calendar','Check-ins on your terms','Choose whether and when to receive a message.')}${feature('shield','A connection you control','Review what is shared before linking an account, and disconnect whenever you choose.')}</div><div class="modal-schedule">Coming soon · No account is linked. This button does not open ${app.name}, request your phone number, or send messages.</div>`,app.icon);},
  memory:()=>showDialog('Your profile, at a glance.',`<p>${profileIsSaved?'These details are saved in this browser.':'These are sample details; you have not saved a profile yet.'}</p><div class="dialog-feature-list">${feature('user','Name',profileValue('name'))}${feature('user','Age range',profileValue('age'))}${feature('pin','City',profileValue('city'))}${feature('clock','Everyday life',profileValue('life'))}${feature('book','Skincare experience',profileValue('experience'))}${feature('heart','Budget preference',profileValue('budget'))}${feature('bottle','Routine',profileValue('routine'))}${feature('shield','Sensitivities',profileValue('sensitivities'))}</div><p>You can change these details in My profile. There is no connected AI memory or cloud account.</p>`,'shield'),
  delete:()=>showDialog('Start fresh on this browser?',`<p>This removes your locally saved profile, including any sensitivities you entered, and restores the Jamie Chan sample. It does not clear any other website data.</p><button class="button plum" data-action="confirm-reset">Reset my saved profile</button> <button class="button outline" data-action="close-dialog">Keep my profile</button>`,'trash'),
  'confirm-reset':()=>{const result=profileStore.reset();if(!result.ok){toast(result.error);return;}savedProfile=result.data;profileIsSaved=false;profileNotice='';dialog.close();renderPage(false);toast('Saved profile removed. The Jamie Chan sample is shown.');}

};
document.addEventListener('click',event=>{
  if(event.target.closest('.skip-link')){event.preventDefault();document.getElementById('main').focus();return;}
  const actionEl=event.target.closest('[data-action]');
  if(actionEl){actions[actionEl.dataset.action]?.(actionEl);return;}
  const period=event.target.closest('[data-period]');
  if(period){routinePeriod=period.dataset.period;renderPage(false);return;}
  const filter=event.target.closest('[data-filter]');
  if(filter){shelfFilter=filter.dataset.filter;renderPage(false);return;}
  const feeling=event.target.closest('[data-feeling]');
  if(feeling){document.querySelectorAll('[data-feeling]').forEach(button=>{const selected=button===feeling;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});toast(`“${feeling.dataset.feeling}” selected for preview. Open a skin check-in to explore the form.`);return;}
  const prompt=event.target.closest('[data-prompt]');
  if(prompt){const input=document.getElementById('chat-message');input.value=prompt.dataset.prompt;input.focus();return;}
  if(event.target.closest('[data-close-on-nav]'))dialog.close();
});
document.addEventListener('submit',event=>{if(!event.target.matches('[data-form]'))return;event.preventDefault();const form=event.target.dataset.form;if(form==='profile'){saveProfile(event.target);return;}const messages={chat:'Conversation preview — the AI is not connected, so your message was not sent.',checkin:'Check-in preview — no photo, symptoms, or notes were saved.'};toast(messages[form]);});
document.addEventListener('input',event=>{if(!event.target.closest('form[data-form="profile"]'))return;const status=document.getElementById('profile-save-status');status.classList.remove('error');status.textContent='Unsaved changes. Choose Save my preferences before leaving this page.';});
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
document.addEventListener('keydown',event=>{const sidebar=document.querySelector('.sidebar');if(!sidebar.classList.contains('open'))return;if(event.key==='Escape'){actions['close-menu']();return;}if(event.key==='Tab'){const items=[...sidebar.querySelectorAll('a,button')].filter(el=>el.getClientRects().length);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
mobileQuery.addEventListener('change',closeMenu);
window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();renderPage();document.getElementById('main').focus({preventScroll:true});});
fillIcons();renderPage();
